def ligar_agendamentos_antigos(apps, schema_editor):
    """Cria um horário para cada agendamento ativo já existente e liga os dois.

    Assim, quem já tinha dados antes desta versão continua com tudo consistente:
    o horário aparece como reservado e não pode ser vendido duas vezes.
    """
    Agendamento = apps.get_model("salao", "Agendamento")
    Horario = apps.get_model("salao", "HorarioDisponivel")
    ativos = Agendamento.objects.exclude(status="CANC").select_related("servico")
    for ag in ativos:
        horario, _ = Horario.objects.get_or_create(
            profissional_id=ag.profissional_id,
            inicio=ag.data_hora,
            defaults={"fim": ag.data_hora + timedelta(minutes=ag.servico.duracao_min)},
        )
        ag.horario = horario
        ag.save(update_fields=["horario"])


